/*===========================
    clients-01 css 
===========================*/
.client-logo-area .section-title-two {
  text-align: center;
  max-width: 550px;
  margin: auto;
  margin-bottom: 50px;
  position: relative;
  z-index: 5;
}
@media only screen and (min-width: 768px) and (max-width: 991px) {
  .client-logo-area .section-title-two {
    margin-bottom: 45px;
  }
}
@media (max-width: 767px) {
  .client-logo-area .section-title-two {
    margin-bottom: 35px;
  }
}
.client-logo-area .section-title-two span {
  text-transform: capitalize;
  color: var(--white);
  background: var(--primary);
  display: inline-block;
  margin-bottom: 10px;
  padding: 5px 15px;
  border-radius: 4px;
}
.client-logo-area .section-title-two h2 {
  margin-bottom: 15px;
}
@media only screen and (min-width: 768px) and (max-width: 991px) {
  .client-logo-area .section-title-two h2 {
    font-size: 2rem;
    line-height: 2.8rem;
  }
}
@media (max-width: 767px) {
  .client-logo-area .section-title-two h2 {
    font-size: 1.5rem;
    line-height: 1.9rem;
  }
}
.client-logo-area .section-title-two p {
  color: var(--dark-3);
}

/*===== Client Logo One =====*/
.client-logo-one {
  padding-top: 100px;
  padding-bottom: 100px;
}
.client-logo-one .single-client {
  margin-top: 30px;
}

/*===== CLIENT STYLE 2 =====*/
.primary-btn { background: var(--secondary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--secondary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--secondary); color: var(--secondary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--secondary); color: var(--white); }
.clients-style-3 { background: var(--light-2); padding: 70px 0; }
.clients-style-3 .section-box { background: var(--white); border: 1px solid var(--gray-4); border-radius: 16px; padding: 42px 34px; box-shadow: var(--shadow-2); }
.clients-style-3 .tag-label { color: var(--secondary); font-size: 13px; font-weight: 700; letter-spacing: .06em; }
.clients-style-3 h2, .clients-style-3 h5 { color: var(--black); }
.clients-style-3 p { color: var(--dark-2); }
.clients-style-3 .mini-card { padding: 24px; border-radius: 12px; background: var(--light-2); border: 1px solid var(--gray-4); height: 100%; }
.clients-style-3 .mini-card i { color: var(--secondary); }

